const apifyItems = [];
try {
  const raw = $('HTTP - Apify Scrape').all();
  if (raw && raw[0] && !raw[0].json.error) {
    const data = Array.isArray(raw[0].json) ? raw[0].json : [raw[0].json];
    for (const post of data) {
      if (post && (post.caption || post.title)) {
        apifyItems.push({
          source_type: 'instagram',
          source_account: post.ownerUsername ? '@' + post.ownerUsername : '@unknown',
          title: (post.caption || post.title || '').substring(0, 120),
          content: post.caption || post.description || '',
          url: post.shortCode ? 'https://www.instagram.com/p/' + post.shortCode + '/' : (post.url || ''),
          engagement: (post.likesCount || 0) + (post.commentsCount || 0),
          date: post.timestamp || new Date().toISOString(),
          language: 'en'
        });
      }
    }
  }
} catch(e) { /* apify failed, continue */ }

function parseRSS(nodeData, sourceName) {
  const items = [];
  try {
    if (!nodeData || !nodeData[0]) return items;
    const item = nodeData[0];
    if (item.json && item.json.error) return items;
    const xml = item.json.data || item.json.body || String(item.json) || '';
    const rx = /<item[^>]*>([\s\S]*?)<\/item>/g;
    let m;
    let count = 0;
    while ((m = rx.exec(xml)) !== null && count < 8) {
      const x = m[1];
      const g = (t) => {
        const r = x.match(new RegExp('<' + t + '[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\/' + t + '>', 'i'));
        return r ? r[1].trim() : '';
      };
      const title = g('title');
      if (title) {
        items.push({
          source_type: 'rss',
          source_account: sourceName,
          title: title,
          content: g('description') || g('summary') || '',
          url: g('link') || '',
          engagement: 0,
          date: g('pubDate') ? new Date(g('pubDate')).toISOString() : new Date().toISOString(),
          language: 'en'
        });
        count++;
      }
    }
  } catch(e) {}
  return items;
}

const allItems = [
  ...apifyItems,
  ...parseRSS($('HTTP - RSS Anthropic').all(), 'Anthropic Blog'),
  ...parseRSS($('HTTP - RSS OpenAI').all(), 'OpenAI Blog'),
  ...parseRSS($('HTTP - RSS TechCrunch').all(), 'TechCrunch AI')
];

allItems.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
const top20 = allItems.slice(0, 20);

if (top20.length === 0) {
  top20.push({
    source_type: 'rss', source_account: 'TechCrunch AI',
    title: 'AI aduce schimbari majore in industrie',
    content: 'Inteligenta artificiala continua sa transforme modul in care lucram si comunicam.',
    url: 'https://techcrunch.com', engagement: 0,
    date: new Date().toISOString(), language: 'en'
  });
}

return [{ json: {
  sources: top20,
  sources_text: JSON.stringify(top20, null, 2),
  total_sources: allItems.length,
  collected_at: new Date().toISOString()
}}];

let selection = null;
try {
  const raw = $input.first().json;
  const text = raw.message?.content || raw.choices?.[0]?.message?.content || raw.text || raw.content || '';
  const clean = text.trim().replace(/^```json\n?/, '').replace(/```$/, '').trim();
  selection = JSON.parse(clean);
} catch(e) {
  selection = {
    selected_source: { title: 'AI si Viitorul Muncii', url: 'https://techcrunch.com', source_type: 'rss', source_account: 'TechCrunch AI' },
    post_type: 'CAROUSEL_EDUCATIONAL',
    post_angle_ro: 'Cum schimba AI-ul piata muncii pentru romani — ce skills sa inveti acum',
    why_selected: 'Fallback — parser error',
    slides_count: 6
  };
}

const generatorPrompt = 'Sursa selectata:\n' + JSON.stringify(selection.selected_source, null, 2) +
  '\n\nTip postare: ' + selection.post_type +
  '\n\nUnghi propus (in romana): ' + selection.post_angle_ro +
  '\n\nNumar slides dorit: ' + (selection.slides_count || 6);

return [{ json: { ...selection, generator_prompt: generatorPrompt } }];

let content = null;
try {
  const raw = $input.first().json;
  const text = raw.message?.content || raw.choices?.[0]?.message?.content || raw.text || raw.content || '';
  const clean = text.trim().replace(/^```json\n?/, '').replace(/```$/, '').trim();
  content = JSON.parse(clean);
} catch(e) {
  throw new Error('Content Generator JSON parse failed. Raw: ' + JSON.stringify($input.first().json).substring(0, 300));
}

if (!content.slides || !Array.isArray(content.slides) || content.slides.length < 2) {
  throw new Error('Generated content missing slides array or too few slides');
}

content.post_id = content.post_id || 'POST-' + Date.now();
content.created_at = new Date().toISOString();
content.slides_count = content.slides.length;

content.slides = content.slides.map((s, i) => ({
  slide_number: s.slide_number || (i + 1),
  type: s.type || (i === 0 ? 'thumbnail' : i === content.slides.length - 1 ? 'cta' : 'content'),
  heading: s.heading || '',
  body: s.body || '',
  subheading: s.subheading || '',
  emoji: s.emoji || '',
  icon: s.icon || s.emoji || ''
}));

return [{ json: content }];

const content = $input.first().json;
const slides = content.slides || [];
const total = slides.length;

function esc(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

const fonts = '<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;700;900&family=DM+Sans:wght@400;500&display=swap" rel="stylesheet">';
const baseCSS = '*{margin:0;padding:0;box-sizing:border-box}body{width:1080px;height:1350px;overflow:hidden;font-family:\'Space Grotesk\',sans-serif;display:flex;flex-direction:column;position:relative}.hdr{position:absolute;top:40px;left:50px;right:50px;display:flex;justify-content:space-between;align-items:center}.hdl{color:#94A3B8;font-size:22px}.sln{color:#4F46E5;font-size:22px}.bot{position:absolute;bottom:0;left:0;right:0;height:6px;background:linear-gradient(90deg,#4F46E5,#06B6D4);border-radius:0}';

const results = [];

for (const slide of slides) {
  const num = String(slide.slide_number || 1).padStart(2,'0');
  const tot = String(total).padStart(2,'0');
  const isThumb = slide.type === 'thumbnail' || slide.slide_number === 1;
  const isCTA = slide.type === 'cta' || slide.slide_number === total;
  let html = '';

  if (isThumb) {
    html = `<!DOCTYPE html><html><head><meta charset="UTF-8">${fonts}<style>${baseCSS}body{background:linear-gradient(135deg,#0A0A0A 0%,#1a1a2e 50%,#0d0d1a 100%);justify-content:center;align-items:center}.ej{font-size:100px;text-align:center;margin-bottom:40px;line-height:1.2}.ttl{font-size:68px;font-weight:900;color:#fff;line-height:1.15;text-align:center;padding:0 80px}.sub{font-size:34px;color:#06B6D4;text-align:center;margin-top:24px;padding:0 80px;font-family:'DM Sans',sans-serif}</style></head><body><div class="hdr"><span class="hdl">@CONFIG_CONT_INSTAGRAM</span><span class="sln">${num}/${tot}</span></div><div class="ej">${esc(slide.emoji||'🤖')}</div><h1 class="ttl">${esc(slide.heading||content.title||'AI azi')}</h1>${slide.subheading?`<p class="sub">${esc(slide.subheading)}</p>`:''}<div class="bot"></div></body></html>`;
  } else if (isCTA) {
    html = `<!DOCTYPE html><html><head><meta charset="UTF-8">${fonts}<style>${baseCSS}body{background:linear-gradient(135deg,#4F46E5 0%,#06B6D4 100%);justify-content:center;align-items:center;text-align:center}.cw{padding:0 80px}.ct{font-size:68px;font-weight:900;color:#fff;line-height:1.2;margin-bottom:40px}.sb{font-size:34px;color:rgba(255,255,255,0.9);font-family:'DM Sans',sans-serif;margin-bottom:24px}.ac{font-size:40px;font-weight:700;color:#fff}</style></head><body><div class="hdr"><span class="hdl" style="color:rgba(255,255,255,0.8)">@CONFIG_CONT_INSTAGRAM</span><span class="sln" style="color:rgba(255,255,255,0.6)">${num}/${tot}</span></div><div class="cw"><p class="ct">${esc(slide.heading||'Salveaz\u0103 postarea! \uD83D\uDD16')}</p><p class="sb">${esc(slide.body||'Urm\u0103re\u0219te pentru mai mult con\u021Binut AI')}</p><p class="ac">@CONFIG_CONT_INSTAGRAM</p></div></body></html>`;
  } else {
    html = `<!DOCTYPE html><html><head><meta charset="UTF-8">${fonts}<style>${baseCSS}body{background:linear-gradient(135deg,#0A0A0A 0%,#1a1a2e 50%,#0d0d1a 100%);justify-content:center;align-items:flex-start;padding:120px 80px 80px 80px}.ic{font-size:72px;margin-bottom:36px}.hd{font-size:50px;font-weight:700;color:#fff;line-height:1.2;margin-bottom:24px}.al{width:80px;height:4px;background:linear-gradient(90deg,#4F46E5,#06B6D4);margin-bottom:28px;border-radius:2px}.bd{font-size:30px;color:#E2E8F0;line-height:1.7;font-family:'DM Sans',sans-serif}</style></head><body><div class="hdr"><span class="hdl">@CONFIG_CONT_INSTAGRAM</span><span class="sln">${num}/${tot}</span></div><div class="ic">${esc(slide.icon||slide.emoji||'\uD83D\uDCA1')}</div><h2 class="hd">${esc(slide.heading||'')}</h2><div class="al"></div><p class="bd">${esc(slide.body||'')}</p><div class="bot"></div></body></html>`;
  }

  results.push({
    json: {
      slide_number: slide.slide_number,
      is_thumbnail: isThumb,
      is_cta: isCTA,
      html_content: html,
      post_id: content.post_id,
      title: content.title,
      post_type: content.post_type,
      slides_count: total,
      description: content.description,
      source_credit: content.source_credit,
      created_at: content.created_at
    }
  });
}

return results;

const htmlSlides = $('Code - Generate HTML Slides').all();
const folderData = $('Google Drive - Create Folder').first().json;
const folderId = folderData.id;
const folderLink = 'https://drive.google.com/drive/folders/' + folderId;

return htmlSlides.map(item => ({
  json: {
    ...item.json,
    folder_id: folderId,
    folder_link: folderLink
  }
}));

const content = $('Code - Parse Content Response').first().json;
const folderData = $('Google Drive - Create Folder').first().json;
const folderId = folderData.id;
const folderLink = 'https://drive.google.com/drive/folders/' + folderId;

const desc = content.description || {};
const fullText = [
  '=== INSTAGRAM DESCRIPTION ===',
  '',
  desc.hook || '',
  '',
  desc.body || '',
  '',
  desc.cta || 'Salveaz\u0103 postarea \uD83D\uDD16 \u0219i urm\u0103re\u0219te @CONFIG_CONT_INSTAGRAM',
  '',
  '\u2022'.repeat(30),
  '',
  desc.hashtags || '#AI #InteligenataArtificiala #Romania #Antreprenoriat',
  '',
  '=== SURSA ===',
  content.source_credit || '',
  '',
  '=== META ===',
  'Post ID: ' + content.post_id,
  'Tip: ' + content.post_type,
  'Slides: ' + content.slides_count,
  'Ora sugerata: ' + (content.suggested_post_time || '18:00'),
  'Generat: ' + content.created_at
].join('\n');

const descBuf = Buffer.from(fullText, 'utf8');
return [{
  json: {
    description_text: fullText,
    folder_id: folderId,
    folder_link: folderLink,
    post_id: content.post_id,
    title: content.title,
    post_type: content.post_type,
    slides_count: content.slides_count,
    description: content.description,
    source_credit: content.source_credit,
    created_at: content.created_at,
    suggested_post_time: content.suggested_post_time || '18:00'
  },
  binary: {
    description_file: {
      data: descBuf.toString('base64'),
      mimeType: 'text/plain',
      fileName: 'descriere.txt',
      fileExtension: 'txt'
    }
  }
}];

const prev = $('Code - Generate Description').first().json;
const curatorData = $('Code - Parse Curator Response').first().json;

const metadata = {
  post_id: prev.post_id,
  title: prev.title,
  post_type: prev.post_type,
  slides_count: prev.slides_count,
  source_url: curatorData.selected_source?.url || '',
  source_account: curatorData.selected_source?.source_account || '',
  source_type: curatorData.selected_source?.source_type || '',
  post_angle: curatorData.post_angle_ro || '',
  source_credit: prev.source_credit,
  drive_folder: prev.folder_link,
  created_at: prev.created_at,
  description_hook: prev.description?.hook || '',
  description_cta: prev.description?.cta || '',
  hashtags: prev.description?.hashtags || '',
  suggested_post_time: prev.suggested_post_time || '18:00',
  status: 'GENERATED'
};

const metaBuf = Buffer.from(JSON.stringify(metadata, null, 2), 'utf8');
return [{
  json: {
    metadata_json: JSON.stringify(metadata, null, 2),
    metadata: metadata,
    ...prev,
    source_url: curatorData.selected_source?.url || '',
    source_account: curatorData.selected_source?.source_account || '',
    source_type: curatorData.selected_source?.source_type || ''
  },
  binary: {
    metadata_file: {
      data: metaBuf.toString('base64'),
      mimeType: 'application/json',
      fileName: 'metadata.json',
      fileExtension: 'json'
    }
  }
}];

const content = $('Code - Parse Content Response').first().json;
const descData = $('Code - Generate Description').first().json;
const curator = $('Code - Parse Curator Response').first().json;

return [{
  json: {
    post_id: content.post_id,
    title: content.title,
    post_type: content.post_type,
    slides_count: content.slides_count,
    description: content.description,
    source_credit: content.source_credit,
    created_at: content.created_at,
    suggested_post_time: content.suggested_post_time || '18:00',
    folder_id: descData.folder_id,
    folder_link: descData.folder_link,
    source_url: curator.selected_source?.url || '',
    source_account: curator.selected_source?.source_account || '',
    source_type: curator.selected_source?.source_type || '',
    post_angle: curator.post_angle_ro || '',
    why_selected: curator.why_selected || ''
  }
}];

